curl -s -X POST "https://slack.com/api/conversations.list?token=<TOKEN>&types=public_channel&limit=1000" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if not data.get('ok'):
    print('Error:', data)
else:
    for c in data.get('channels', []):
        if 'payments' in c['name']:
            print(c['id'], c['name'], 'archived' if c.get('is_archived') else 'active')
"
